{
  "passageId": "fear-appeal-persuasion",
  "items": [
    {
      "id": "R1",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "기존 연구가 설득 효과를 다루지 않았다는 연구 상황이 재니스의 새로운 연구 초점이 등장한 배경이므로 2번에 해당한다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "세 수준을 비교한 실험이 중간 수준의 설득 효과가 가장 크다는 발견을 뒷받침하는 근거이므로 9번에 해당한다."
    },
    {
      "id": "R3",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "레벤달이 재니스의 연구를 감정적 측면에 편중되었다고 명시적으로 문제 삼으므로 1번의 비판에 해당한다."
    },
    {
      "id": "R4",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "감정에만 치우쳤다는 연구의 한계에 대해 인지적 반응까지 포함하는 보완 설명을 제시하므로 4번에 해당한다."
    },
    {
      "id": "R5",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "앞서 언급한 감정적 반응에 공포 통제 반응이라는 이름을 붙이므로 8번의 명명에 해당한다."
    },
    {
      "id": "R6",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "앞서 언급한 인지적 반응에 위험 통제 반응이라는 이름을 붙이므로 8번의 명명에 해당한다."
    },
    {
      "id": "R7",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "동일한 이론 안의 두 반응을 위험 무시와 권고 이행이라는 서로 다른 행동 결과로 비교하므로 14번에 해당한다."
    },
    {
      "id": "R8",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "위티가 재니스와 레벤달의 선행 연구를 받아들여 종합하므로 1번의 수용에 해당한다."
    },
    {
      "id": "R9",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "설득 효과의 두 요인을 제시한 뒤 그중 위협의 수준이 높다는 것이 무엇인지 자세히 설명하므로 7번에 해당한다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "설득 효과의 두 요인을 제시한 뒤 그중 효능감의 수준이 높은 경우를 자세히 설명하므로 7번에 해당한다."
    },
    {
      "id": "R11",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "위협 수준을 판단하는 일반 기준을 동호회 회원 자격 상실이라는 구체적 상황에 가져다 쓰므로 6번에 해당한다."
    },
    {
      "id": "R12",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "효능감 수준을 판단하는 일반 기준을 동호회 모임 참석 권고와 이행 능력의 사례에 적용하므로 6번에 해당한다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "안내문의 회원 자격 상실이라는 위험을 애착이 강한 회원이 어떻게 받아들이는지 같은 사례 안에서 구체화하므로 7번에 해당한다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "안내문의 참석 권고를 이행하기 쉽다고 느끼는 회원의 경우로 같은 사례를 더 자세히 설명하므로 7번에 해당한다."
    },
    {
      "id": "R15",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "위협과 효능감의 의미를 설명하는 단계에서 두 요인을 통제 반응과 연결하는 단계로 논의가 나아가므로 3번에 해당한다."
    },
    {
      "id": "R16",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "위티가 레벤달의 두 통제 반응 구분을 받아들여 자신의 설명에 활용하므로 1번의 수용에 해당한다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "두 요인과 통제 반응을 연결해 결론을 냈다는 진술을 구체적인 조건별 결론으로 풀어 주므로 7번에 해당한다."
    },
    {
      "id": "R18",
      "type": "CONDITION",
      "otherName": "",
      "reason": "위협이 높다는 공통 조건에서 효능감의 높고 낮음에 따라 작동하는 반응이 갈리므로 11번에 해당한다."
    },
    {
      "id": "R19",
      "type": "CONDITION",
      "otherName": "",
      "reason": "위협 수준이 높은 경우와 낮은 경우에 따라 통제 반응의 작동 여부와 효능감의 역할이 갈리므로 11번에 해당한다."
    },
    {
      "id": "R20",
      "type": "CAUSE",
      "otherName": "",
      "reason": "위협이 자신에게 영향을 주지 않는다는 수용자의 인식이 공포 소구에 반응하지 않는 결과를 실제로 일으키므로 10번에 해당한다."
    },
    {
      "id": "R21",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "위티가 레벤달의 위험 통제 반응 설명을 받아들이고 그 반응의 작동 조건을 덧붙이므로 1번의 수용에 해당한다."
    },
    {
      "id": "R22",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "위티가 레벤달의 공포 통제 반응 설명을 받아들이고 그 반응의 작동 조건을 덧붙이므로 1번의 수용에 해당한다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "기존 공포 소구 이론을 통합했다는 사실이 후속 연구의 중요한 디딤돌이라는 평가를 뒷받침하므로 9번에 해당한다."
    }
  ]
}

